def slicev(self, node):
    if isinstance(node, ast.Slice):
        if node.lower:
            self.visit(node.lower)
        if node.upper:
            self.visit(node.upper)
        if node.step:
            self.visit(node.step)
    elif isinstance(node, ast.ExtSlice):
        if node.dims:
            for d in node.dims:
                self.visit(d)
    else:
        self.visit(node.value)

