def get_elements(self, number):
    if number == 0:
        return []

    elements = list()
    # Turn number into a binary string of length len(self.bv2el)
    binary_string = format(number,
                           '0' + str(len(self.bv2el)) + 'b')
    for i, bit in enumerate(binary_string):
        if bit == '1':
            elements.append(self.bv2el[i])
    return elements

